+def _selection_confirmation_evidence(logs: dict[str, str], run_ids: dict[str, str],
+                                     case: dict[str, Any]) -> dict[str, Any]:
+    characters, stages = {}, []
+    for label in ("host", "sandbox"):
+        prefix = r"run_id=" + re.escape(run_ids[label]) + r" detail="
+        rows = list(re.finditer(prefix + r"character_confirmed:side=([01]):code=([^:\s]+):timer_before=(\d+)", logs[label]))
+        if len(rows) != 1:
+            raise RuntimeError(f"{label} lacks one accepted character confirmation before timer expiry")
+        side, code, timer = int(rows[0][1]), rows[0][2], int(rows[0][3])
+        if timer <= 0 or code != case["fighter_order"][side]:
+            raise RuntimeError("character confirmation has wrong content or expired timer")
+        characters[label] = {"side": side, "code": code, "timer_before": timer}
+        for row in re.finditer(prefix + r"stage_confirmed:code=([^:\s]+):timer_before=(\d+)", logs[label]):
+            if row[1] != case["stage_package_root"].rsplit("/", 1)[-1] or int(row[2]) <= 0:
+                raise RuntimeError("stage confirmation has wrong content or expired timer")
+            stages.append({"peer": label, "code": row[1], "timer_before": int(row[2])})
+    if {row["side"] for row in characters.values()} != {0, 1} or len(stages) != 1:
+        raise RuntimeError("setup lacks both character decisions and the active peer's stage confirmation")
+    return {"characters": characters, "stage": stages[0]}
+
