+            sync->GetPropertyByNameInChain(L"OnRecvBattleSync"));
+        if (property)
+        {
+            // UE4.17 stores the multicast invocation list inline. The
+            // GetMulticastDelegate virtual was added in UE4.23; UE4SS throws
+            // for that wrapper on this game. Inspect the reflected slot.
+            static_assert(sizeof(RC::Unreal::FMulticastScriptDelegate) == 0x10);
